package cz.videotranscript.app;
import android.app.Activity;import android.os.Bundle;import android.content.Intent;import android.net.Uri;import android.widget.*;import java.util.regex.*;
public class MainActivity extends Activity {
 EditText input; TextView status;
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(32,64,32,32);TextView title=new TextView(this);title.setText("VideoTranscript");title.setTextSize(28);l.addView(title);input=new EditText(this);input.setHint("Odkaz na YouTube");l.addView(input);status=new TextView(this);status.setText("Vývojová verze – lokální přepis zatím není připojen.");l.addView(status);Button btn=new Button(this);btn.setText("Otevřít video");l.addView(btn);btn.setOnClickListener(v->{String id=extract(input.getText().toString());if(id==null){status.setText("Neplatný YouTube odkaz.");return;}startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.youtube.com/watch?v="+id)));});Button cap=new Button(this);cap.setText("Zachytit interní zvuk");l.addView(cap);cap.setOnClickListener(v->{if(android.os.Build.VERSION.SDK_INT<29){status.setText("Vyžaduje Android 10.");return;}if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},8);return;}startActivityForResult(getSystemService(android.media.projection.MediaProjectionManager.class).createScreenCaptureIntent(),9);});Button stop=new Button(this);stop.setText("Ukončit záznam");l.addView(stop);stop.setOnClickListener(v->{stopService(new Intent(this,CaptureService.class));status.setText("Záznam ukončen. Přepis zatím není připojen.");});setContentView(l);if(Intent.ACTION_SEND.equals(getIntent().getAction()))input.setText(getIntent().getStringExtra(Intent.EXTRA_TEXT));}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==9&&result==RESULT_OK&&data!=null){startForegroundService(new Intent(this,CaptureService.class).putExtra("code",result).putExtra("data",data));status.setText("Po zahájení záznamu přehrajte video v Brave. Záznam nejvýše 15 minut.");}}
 static String extract(String s){Matcher m=Pattern.compile("https?://(?:www\\.|m\\.)?(?:youtu\\.be/|youtube\\.com/(?:watch\\?v=|shorts/))([A-Za-z0-9_-]{11})(?![A-Za-z0-9_-])").matcher(s);return m.find()?m.group(1):null;}
}